def modulusPreservingL1Family (T : Lp ℝ 1 μ →L[ℝ] Lp ℝ 1 ν) :
    Set (Submodule ℝ (Lp ℝ 1 μ)) :=
  {P | ∃ (m : MeasurableSpace X) (hm : m ≤ m₀),
    @CountablyGenerated X m ∧ P = lOneSubsigma μ m ∧ L1SubsigmaPreservesModulus T hm}

